"""
Invoice export to the billing API (written against pydantic 1.10).

Provides:
  - export_invoice(data: dict) -> str
"""
from __future__ import annotations

from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List

from pydantic import BaseModel, ValidationError, validator
from pydantic.json import ENCODERS_BY_TYPE


def _to_utc_datetime(value: datetime) -> datetime:
    """Convert naive datetimes to UTC; convert aware datetimes to UTC."""
    if value.tzinfo is None or value.tzinfo.utcoffset(value) is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _format_issued_at_utc_z(dt: datetime) -> str:
    """YYYY-MM-DDTHH:MM:SSZ in UTC (second precision)."""
    dt_utc = _to_utc_datetime(dt)
    return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")


def _quantize_2dp(d: Decimal) -> Decimal:
    # Convert to exactly 2 decimal places (billing API expects that exact form)
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class InvoiceLine(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_min_1(cls, v: int) -> int:
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_non_negative(cls, v: Any) -> Any:
        # Let pydantic parse into Decimal; then validate constraints in a second validator.
        return v

    @validator("unit_price")
    def unit_price_constraints(cls, v: Decimal) -> Decimal:
        if v < 0:
            raise ValueError("unit_price must be >= 0")
        # Ensure it is representable with at most 2 decimal places; then quantize.
        quantized = _quantize_2dp(v)
        if v != quantized:
            # Reject inputs with more than 2 decimals to avoid silently rounding.
            raise ValueError("unit_price must have at most 2 decimal places")
        return quantized


class InvoiceExportModel(BaseModel):
    number: str
    issued_at: datetime
    lines: List[InvoiceLine]

    class Config:
        # We'll custom-encode issued_at with required format for the billing API.
        json_encoders = {
            datetime: _format_issued_at_utc_z,
            Decimal: lambda d: f"{_quantize_2dp(d):.2f}",
        }

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v: Any) -> Any:
        # pydantic parses ISO strings already; we only need to ensure timezone handling later.
        return v

    @validator("issued_at")
    def issued_at_to_utc(cls, v: datetime) -> datetime:
        return _to_utc_datetime(v)

    def export_dict(self) -> dict:
        total = sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))
        total_q = _quantize_2dp(total)

        return {
            "number": self.number,
            "issued_at": _format_issued_at_utc_z(self.issued_at),
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    # Exactly two decimals as a string
                    "unit_price": f"{_quantize_2dp(line.unit_price):.2f}",
                }
                for line in self.lines
            ],
            # Total is required as a string with exactly two decimals
            "total": f"{total_q:.2f}",
        }


def export_invoice(data: dict) -> str:
    """
    Validate invoice input and return billing-API JSON text.

    Expected input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive values treated as UTC)
      - lines: list of dicts with
          - sku (str)
          - quantity (int >= 1)
          - unit_price (Decimal >= 0; provided as str/int/float)

    Output JSON:
      - number
      - issued_at: "YYYY-MM-DDTHH:MM:SSZ"
      - lines: [{"sku", "quantity", "unit_price"}] where unit_price is a string with exactly 2 decimals
      - total: string with exactly 2 decimals (sum(quantity * unit_price))

    Raises ValueError for invalid input.
    """
    try:
        model = InvoiceExportModel.parse_obj(data)
    except ValidationError as e:
        # Callers rely on ValueError semantics for invalid inputs.
        raise ValueError(str(e)) from e

    # Produce JSON with the exact required shapes/encodings.
    # Use BaseModel's JSON utilities for consistent formatting.
    # But we must ensure unit_price/total formatting is exact strings with 2 decimals.
    payload = model.export_dict()
    return BaseModel.parse_obj(payload).json()  # not suitable for exact structure typing

from __future__ import annotations

import json
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import Any, List, Optional, Union

from pydantic import BaseModel, ConfigDict, ValidationError, field_validator


_TWO_PLACES = Decimal("0.01")


def _ensure_utc_second_precision_z(dt: datetime) -> str:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    else:
        dt = dt.astimezone(timezone.utc)
    dt = dt.replace(microsecond=0)
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


def _to_decimal_2dp_str(v: Any) -> str:
    """
    Convert input (str/int/float/Decimal) to Decimal with exactly 2 decimal places,
    and return as a string with exactly two decimals.
    """
    try:
        if isinstance(v, Decimal):
            d = v
        elif isinstance(v, (int, str)):
            d = Decimal(str(v))
        elif isinstance(v, float):
            d = Decimal(str(v))
        else:
            raise TypeError(f"unsupported type: {type(v).__name__}")
    except Exception as e:
        raise ValueError("unit_price must be a decimal number") from e

    # Enforce >= 0, and normalize to exactly 2 decimal places for export.
    if d < 0:
        raise ValueError("unit_price must be >= 0")

    d = d.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)
    # Ensure exactly two decimals in string form.
    return format(d, "f")


class _Line(BaseModel):
    model_config = ConfigDict(extra="forbid")

    sku: str
    quantity: int
    unit_price: Decimal

    @field_validator("sku")
    @classmethod
    def _validate_sku(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError("sku must be a string")
        s = v.strip()
        if not s:
            raise ValueError("sku must not be blank")
        return s

    @field_validator("quantity", mode="before")
    @classmethod
    def _coerce_quantity(cls, v: Any) -> int:
        # Let pydantic handle most coercion; just ensure type/value semantics.
        if isinstance(v, bool):
            raise ValueError("quantity must be an integer >= 1")
        if isinstance(v, float):
            if not v.is_integer():
                raise ValueError("quantity must be an integer >= 1")
            v = int(v)
        try:
            q = int(v)
        except Exception as e:
            raise ValueError("quantity must be an integer >= 1") from e
        if q < 1:
            raise ValueError("quantity must be >= 1")
        return q

    @field_validator("unit_price", mode="before")
    @classmethod
    def _coerce_unit_price(cls, v: Any) -> Decimal:
        # Parse via the same rules as export; store as Decimal for summation.
        if isinstance(v, Decimal):
            d = v
        elif isinstance(v, (int, str)):
            d = Decimal(str(v))
        elif isinstance(v, float):
            d = Decimal(str(v))
        else:
            raise ValueError("unit_price must be a decimal number")

        if d < 0:
            raise ValueError("unit_price must be >= 0")

        # Normalize to 2dp to keep total consistent with the exported unit_price strings.
        return d.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)


class _Invoice(BaseModel):
    model_config = ConfigDict(extra="forbid")

    number: str
    issued_at: datetime
    lines: List[_Line]

    @field_validator("number", mode="before")
    @classmethod
    def _coerce_number(cls, v: Any) -> str:
        if isinstance(v, bool) or v is None:
            raise ValueError("number must be a string")
        if isinstance(v, (int, float)):
            # Accept but normalize to string.
            return str(v)
        if not isinstance(v, str):
            raise ValueError("number must be a string")
        s = v.strip()
        if not s:
            raise ValueError("number must not be blank")
        return s

    @field_validator("issued_at", mode="before")
    @classmethod
    def _coerce_issued_at(cls, v: Any) -> datetime:
        if isinstance(v, datetime):
            return v
        if not isinstance(v, str):
            raise ValueError("issued_at must be an ISO 8601 string or a datetime")
        s = v.strip()
        if not s:
            raise ValueError("issued_at must not be blank")
        # datetime.fromisoformat doesn't handle trailing 'Z' in older patterns; support it.
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.fromisoformat(s)
        except Exception as e:
            raise ValueError("issued_at must be a valid ISO 8601 datetime") from e
        return dt


def export_invoice(data: dict) -> str:
    """
    Validate an invoice and return JSON for the billing API.

    Output:
      - number
      - issued_at formatted as 'YYYY-MM-DDTHH:MM:SSZ' in UTC
      - lines: [{sku, quantity, unit_price}] where unit_price is a string with exactly two decimals
      - total: sum(quantity * unit_price), as a string with exactly two decimals
    """
    try:
        invoice = _Invoice.model_validate(data)
    except ValidationError as e:
        raise ValueError(str(e)) from e
    except ValueError:
        # Re-raise ValueError directly.
        raise

    issued_at_z = _ensure_utc_second_precision_z(invoice.issued_at)

    lines_out: List[dict[str, Any]] = []
    total = Decimal("0")
    for line in invoice.lines:
        unit_price_d: Decimal = line.unit_price
        total += Decimal(line.quantity) * unit_price_d
        lines_out.append(
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit_price": _to_decimal_2dp_str(unit_price_d),
            }
        )

    total_d = total.quantize(_TWO_PLACES, rounding=ROUND_HALF_UP)
    payload = {
        "number": invoice.number,
        "issued_at": issued_at_z,
        "lines": lines_out,
        "total": format(total_d, "f"),
    }
    return json.dumps(payload, ensure_ascii=False, separators=(",", ":"))

from __future__ import annotations

from typing import Any, Dict, List

from pydantic import ValidationError

from profile_models import Profile


def import_profiles(rows: list) -> list:
    """
    Validate profile rows (dicts) and return only the valid ones as dicts, in input order.

    Each returned dict has exactly:
      {"user_id": int, "display_name": str, "bio": str | None, "zip_code": str}

    Invalid rows are silently skipped.
    """
    valid: List[Dict[str, Any]] = []

    for row in rows:
        try:
            if not isinstance(row, dict):
                continue
            profile = Profile.model_validate(row)
            valid.append(
                {
                    "user_id": profile.user_id,
                    "display_name": profile.display_name,
                    "bio": profile.bio,
                    "zip_code": profile.zip_code,
                }
            )
        except (ValidationError, ValueError, TypeError):
            continue

    return valid

from __future__ import annotations

from collections.abc import Iterable
from typing import Any, List

from pydantic import BaseModel, ConfigDict, ValidationError


class _CustomerSchema(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: int
    name: str
    email: str


class _ItemSchema(BaseModel):
    model_config = ConfigDict(extra="ignore")

    sku: str
    quantity: int


class _OrderPayloadSchema(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: int
    customer: _CustomerSchema
    items: List[_ItemSchema]


def _require_attr(obj: Any, attr: str) -> Any:
    try:
        return getattr(obj, attr)
    except AttributeError as e:
        raise ValueError(f"Missing attribute '{attr}'") from e


def orders_payload(orders: list) -> list:
    """
    Convert ORM order objects to JSON-ready dicts:
      [{"id": ..., "customer": {"id","name","email"}, "items":[{"sku","quantity"}, ...]}, ...]

    Raises ValueError if a required attribute is missing or has an invalid value.
    """
    if not isinstance(orders, list):
        raise ValueError("orders must be a list")

    payloads: List[dict] = []
    for order in orders:
        order_id = _require_attr(order, "id")
        customer_obj = _require_attr(order, "customer")
        items_obj = _require_attr(order, "items")

        if not isinstance(items_obj, Iterable) or isinstance(items_obj, (str, bytes)):
            raise ValueError("order.items must be an iterable")

        customer = _CustomerSchema.model_validate(
            {
                "id": _require_attr(customer_obj, "id"),
                "name": _require_attr(customer_obj, "name"),
                "email": _require_attr(customer_obj, "email"),
            }
        )

        items: List[_ItemSchema] = []
        for item in items_obj:
            items.append(
                _ItemSchema.model_validate(
                    {"sku": _require_attr(item, "sku"), "quantity": _require_attr(item, "quantity")}
                )
            )

        try:
            validated_order = _OrderPayloadSchema.model_validate(
                {"id": order_id, "customer": customer, "items": items}
            )
        except ValidationError as e:
            # pydantic.ValidationError is a ValueError as required by callers.
            raise e

        payloads.append(validated_order.model_dump())

    return payloads

from __future__ import annotations

from typing import Any, Dict

from pydantic import BaseModel, ConfigDict, ValidationError, field_validator, model_validator

import signup_form


class _SignupPayload(BaseModel):
    model_config = ConfigDict(extra="forbid")

    username: str
    email: str
    password: str
    password_confirm: str
    phone: str

    @field_validator("email", mode="before")
    @classmethod
    def _validate_and_normalise_email(cls, v: Any) -> str:
        if not isinstance(v, str):
            raise ValueError("email must be a string")
        normalized = v.strip().lower()
        if "@" not in normalized:
            raise ValueError('email must contain "@"')
        return normalized

    @field_validator("username", mode="before")
    @classmethod
    def _validate_username(cls, v: Any) -> str:
        # Reuse documented behaviour/regex from the shared skill:
        # parse_signup rejects with ValueError if username doesn't match ^[a-z0-9_]{3,20}$
        if not isinstance(v, str):
            raise ValueError("username must be a string")
        # signup_form already encodes the exact rule; validate by calling parse path.
        # We validate by constructing minimal payload and letting its model_validator raise.
        # (Using its internal rules ensures exact error semantics.)
        try:
            signup_form._SignupPayload.model_validate(
                {
                    "username": v,
                    "password": "aaaaaaaa",  # valid dummy to reach username validation
                    "password_confirm": "aaaaaaaa",
                    "phone": "+12345678",
                }
            )
        except ValidationError as e:
            # Ensure we raise ValueError-compatible behaviour (ValidationError is a ValueError)
            raise e
        except ValueError as e:
            # If it ever raises ValueError directly, keep it as ValueError.
            raise e
        return v

    @field_validator("phone", mode="before")
    @classmethod
    def _validate_phone(cls, v: Any) -> str:
        # Reuse documented phone normalisation rule:
        # spaces/dots/dashes/parentheses removed; must become '+' followed by 8-15 digits.
        return signup_form.PhoneNumber.validate(v)

    @model_validator(mode="after")
    def _validate_passwords(self) -> "_SignupPayload":
        # Reuse documented passwords rules.
        signup_form.SignupForm.passwords_match(
            {"password": self.password, "password_confirm": self.password_confirm}
        )
        return self


def validate_signup(data: Dict[str, Any]) -> Dict[str, Any]:
    """
    Validate a sign-up payload with pydantic.

    Returns:
        {"username": ..., "email": ..., "phone": <compact phone>}

    Raises:
        ValueError / pydantic.ValidationError for any missing or invalid field.
    """
    try:
        payload = _SignupPayload.model_validate(data)
    except ValidationError as e:
        # Callers rely on pydantic.ValidationError being a ValueError.
        raise e

    return {
        "username": payload.username,
        "email": payload.email,
        "phone": payload.phone,
    }
